using System;using System.IO;using System.IO.Compression;using System.Linq;using System.Collections.Generic;using System.Xml.Linq;using AutosurBuscador;
class CoreTests {
 static void Check(bool value,string name){if(!value)throw new Exception(name);Console.WriteLine("OK "+name);}
 static void Main(string[] args){if(args.Length>0){var real=SalesXlsx.Read(args[0]);var realMetrics=SalesMath.Sum(real);Console.WriteLine("REAL "+real.Count+" rows Sale="+realMetrics.Sale+" Profit="+realMetrics.Profit+" Tickets="+realMetrics.Tickets);return;}
 var p=new DateTime(2026,10,1);Check(SalesMath.Period(new DateTime(2026,9,26))==new DateTime(2026,9,1),"Cierre 26");Check(SalesMath.Period(new DateTime(2026,9,27))==p,"Apertura 27");Check(SalesMath.End(new DateTime(2027,1,1))==new DateTime(2027,1,26),"Cruce anual");Check(SalesMath.Start(new DateTime(2026,3,1))==new DateTime(2026,2,27),"Febrero");
 var holidays=new HashSet<DateTime>{new DateTime(2026,10,12)};Check(SalesMath.Workdays(new DateTime(2026,10,9),new DateTime(2026,10,14),holidays)==3,"Laborables sin sábado domingo feriado");
 string tmp=Path.Combine(Path.GetTempPath(),"AutosurTests_"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(tmp);try{
 var zipPath=Path.Combine(tmp,"sample.xlsx");using(var z=ZipFile.Open(zipPath,ZipArchiveMode.Create)){
 Add(z,"xl/workbook.xml","<workbook xmlns='http://schemas.openxmlformats.org/spreadsheetml/2006/main' xmlns:r='http://schemas.openxmlformats.org/officeDocument/2006/relationships'><sheets><sheet name='Ventas' sheetId='1' r:id='rId1'/></sheets></workbook>");
 Add(z,"xl/_rels/workbook.xml.rels","<Relationships xmlns='http://schemas.openxmlformats.org/package/2006/relationships'><Relationship Id='rId1' Target='/xl/worksheets/sheet1.xml'/></Relationships>");
 Add(z,"xl/worksheets/sheet1.xml","<worksheet xmlns='http://schemas.openxmlformats.org/spreadsheetml/2006/main'><sheetData>"+Row(1,new Dictionary<string,string>{{"D","Fecha emisión"},{"K","Boca y Nro de comprobante"},{"CA","Venta a precio final del repuesto"},{"CG","Utilidad (considerando costo de reposición)"}},true)+SaleRow(2,"FACTURA DE VENTA","F","0001",100,30)+SaleRow(3,"FACTURA DE VENTA","F","0001",200,60)+SaleRow(4,"NOTA DE CREDITO","NC","0001",-50,-15)+SaleRow(5,"INTERNA TALLER","INT","0001",20,5)+SaleRow(6,"INTERNA GARANTIA","GAR","0001",0,0)+SaleRow(7,"INTERNA CORTESIA","COR","0001",10,-1)+Row(8,new Dictionary<string,string>{{"CA","480"},{"CG","158"}},false)+"</sheetData></worksheet>");}
 var rows=SalesXlsx.Read(zipPath);Check(rows.Count==6,"Excluye fila total, conserva líneas repetidas");var m=SalesMath.Sum(rows);Check(m.Sale==280&&m.Profit==79&&m.Tickets==4,"Signos y tickets sin notas; clave distingue tipos");Check(SalesMath.Sum(rows.Where(x=>SalesMath.Included(x,true,true,false))).Sale==270,"Excluir Cortesía");Check(SalesMath.Sum(rows.Where(x=>SalesMath.Included(x,false,false,false))).Tickets==1,"Excluir internos y garantía de tickets");Check(m.Margin==79m/280*100,"Margen ponderado");Check(m.Average==70,"Ticket neto por comprobante");Check(SalesMath.Sum(new SaleLine[0]).Average==null,"Sin división por cero");
 var store=new SalesStore(Path.Combine(tmp,"store"));store.Set(new Snapshot{Period=p,Cutoff=new DateTime(2026,10,14),Loaded=DateTime.UtcNow,Lines=rows});store.GetGoal(p).Total=200;store.GetGoal(p).Taller=40;store.CalendarYears.Add(2026);store.Holidays.UnionWith(holidays);store.Save();store.Set(new Snapshot{Period=p,Cutoff=new DateTime(2026,10,14),Loaded=DateTime.UtcNow,Lines=rows});store.Save();var loaded=new SalesStore(Path.Combine(tmp,"store"));Check(loaded.History.Count==1&&SalesMath.Sum(loaded.Get(p).Lines).Sale==280,"Carga repetida reemplaza sin duplicar");Check(loaded.GetGoal(p).Total==200&&loaded.GetGoal(p).Taller==40,"Conserva objetivos y distribución");Check(loaded.HasCalendar(new DateTime(2026,1,1),new DateTime(2026,12,31)),"Calendario persistido");Check(m.Sale/loaded.GetGoal(p).Total*100==140,"Sobreperformance sin tope");Check(File.Exists(Path.Combine(tmp,"store","objetivos.xml.bak")),"Respaldo de historial");
 }finally{Directory.Delete(tmp,true);}Console.WriteLine("Todas las pruebas pasaron.");}
 static void Add(ZipArchive z,string name,string content){using(var s=new StreamWriter(z.CreateEntry(name).Open()))s.Write(content);}
 static string SaleRow(int n,string type,string code,string number,decimal sale,decimal profit){return Row(n,new Dictionary<string,string>{{"A","87800"},{"B","101"},{"D","2026-10-14T00:00:00"},{"H",type},{"I",code},{"J","A"},{"K",number},{"Q","Taller"},{"CA",sale.ToString(System.Globalization.CultureInfo.InvariantCulture)},{"CG",profit.ToString(System.Globalization.CultureInfo.InvariantCulture)}},false);}
 static string Row(int n,Dictionary<string,string> cells,bool allText){XNamespace ns="http://schemas.openxmlformats.org/spreadsheetml/2006/main";var r=new XElement(ns+"row",new XAttribute("r",n));foreach(var cell in cells){bool text=allText||!(cell.Key=="CA"||cell.Key=="CG");var c=new XElement(ns+"c",new XAttribute("r",cell.Key+n));if(text){c.Add(new XAttribute("t","inlineStr"));c.Add(new XElement(ns+"is",new XElement(ns+"t",cell.Value)));}else c.Add(new XElement(ns+"v",cell.Value));r.Add(c);}return r.ToString(SaveOptions.DisableFormatting);}
}
